from collections import deque

def isEulerCircuilt(V, adj):
    if V == 0:
        return 0

    # Check if all non-zero degree vertices are connected
    visited = [False] * V
    start_node = -1
    for i in range(V):
        if len(adj[i]) > 0:
            start_node = i
            break
    if start_node == -1:
        return 2  # empty graph has Eulerian circuit

    queue = deque([start_node])
    visited[start_node] = True
    count = 1

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                count += 1
                queue.append(v)

    for i in range(V):
        if len(adj[i]) > 0 and not visited[i]:
            return 0

    # Check degrees
    odd_degree = 0
    for i in range(V):
        if len(adj[i]) % 2 != 0:
            odd_degree += 1

    if odd_degree == 0:
        return 2
    elif odd_degree == 2:
        return 1
    else:
        return 0
